const text = $json.output || $json.text || '';

// If this looks like an availability list, send as ONE message
if (text.includes('Here are some available appointment times')) {
  return [{ json: { text: text.trim() } }];
}

// Otherwise, keep original behavior (one message per line)
return text
  .split('\n')
  .map(t => t.trim())
  .filter(Boolean)
  .map(t => ({ json: { text: t } }));

// Generate a random delay between 0 and 5 seconds
const delaySeconds = Math.floor(Math.random() * 6);

// Return delay in milliseconds for n8n
return {
  delay: delaySeconds * 1000
};

// Collect all Postgres rows into one array
return [
  {
    json: {
      available_slots: items.map(i => i.json.start_time)
    }
  }
];

