UPDATE appointments
SET status = 'cancelled'
WHERE id = {{ $json.appointment_id }}
RETURNING id, start_time;

UPDATE availability
SET is_booked = false
WHERE start_time = '{{ $json.start_time }}';

SELECT start_time
FROM availability
WHERE is_booked = false
AND (
  {{ $json.from_date ? "start_time >= '" + $json.from_date + "'" : "true" }}
)
AND (
  {{ $json.to_date ? "start_time < '" + $json.to_date + "'" : "true" }}
)
ORDER BY start_time

